<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {createHypothesis,approveHypothesis,downloadHypothesis} from '../api/hypotheses';import {useTask} from '../hooks/useTask';import {features} from '../constants/enums';import {number} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';const route=useRoute(),lab=useResearch(),auth=useAuth(),data=ref({title:'运行排程与计量边界复核',finding_id:Number(route.query.finding)||0,action:'先核对运行排程与计量边界，观察该特征与能耗的关联在建筑现场是否成立。',verification:'安排两周独立现场观察，记录共同变化因素；模型系数与置换重要性不构成因果节能承诺。'}),{busy,error,perform}=useTask();onMounted(()=>perform(async()=>{await lab.load();if(!data.value.finding_id)data.value.finding_id=lab.findings[0]?.id||0;}));function submit(){perform(async()=>{await createHypothesis(data.value);await lab.load();data.value.title='';});}function approve(id:number){perform(async()=>{await approveHypothesis(id);await lab.load();});}</script><template><PageHeading index="05" title="把关联线索，写成现场可验证的问题" text="分析员提出改造假设，工程负责人审阅；未做因果识别，不报告自动节能收益。"/><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="hypothesis-layout" :class="{readonly:!auth.canEdit}"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><h2>新的现场验证假设</h2><label>假设标题<input v-model="data.title" required minlength="2"></label><label>依据驱动解释<select v-model="data.finding_id"><option v-for="f in lab.findings" :key="f.id" :value="f.id">研究#{{f.run_id}} / {{features[f.feature]}} / ΔMAE {{number(f.importance_mean,2)}}</option></select></label><label>行动假设<textarea v-model="data.action" rows="5" minlength="10" required></textarea></label><label>独立验证与解释限制<textarea v-model="data.verification" rows="5" minlength="10" required></textarea></label><button class="primary" :disabled="busy||!data.finding_id">保存待审阅假设 →</button></form><section class="hypothesis-files"><article v-for="h in lab.hypotheses" :key="h.id"><div class="file-heading"><p class="eyebrow">RETROFIT HYPOTHESIS / {{String(h.id).padStart(3,'0')}}</p><StatusBadge :status="h.status"/></div><h2>{{h.title}}</h2><p class="finding-link">{{features[lab.findings.find(f=>f.id===h.finding_id)?.feature||'']}} <span>研究#{{lab.findings.find(f=>f.id===h.finding_id)?.run_id}}</span></p><h3>行动假设</h3><p>{{h.action}}</p><h3>验证与限制</h3><p>{{h.verification}}</p><footer><template v-if="h.status==='draft'"><button v-if="auth.user?.role==='admin'" class="outline" :disabled="busy" @click="approve(h.id)">审阅并批准交付 ✓</button><small>等待工程负责人审阅</small></template><template v-else><small>审阅人 {{h.approved_by}}</small><button class="text-button" :disabled="busy" @click="perform(()=>downloadHypothesis(h.id))">下载改造研究CSV ↓</button></template></footer></article><p v-if="!lab.hypotheses.length" class="muted">先完成模型研究，再从一个驱动解释提出现场验证假设。</p></section></div></template>
